{"renderable":true,"reason":"All three photos show the same white clapboard two-and-a-half storey house: a front-facing gable with two small attic windows, two second-floor windows below it, and a full-width glazed enclosed porch across the ground floor with a door right of centre and steps with handrails. Photo 3 adds the left side: a two-storey projecting bay, a brick chimney, a roof dormer and a big hedge in front of the porch. I rebuilt it as massing boxes: foundation band, two-storey body, triangular gable prism, two sloping roof planes, the porch (skirt, glazing band, head band, roof slab), individual glass panes, the side bay, chimney, dormer, steps, handrails, hedge, trees and a street.","confidence":0.82,"subject":"A two-and-a-half storey white clapboard house with a front-facing gable and a full-width glazed enclosed porch on the ground floor.","subjectKind":"other","name":"Front-gabled white house with enclosed porch","description":"A tall, narrow American clapboard house standing slightly above the street. The main body is a simple two-storey box; above it a steep triangular gable faces the street, with two small square windows side by side near its middle. Two taller sash windows sit on the second floor, centred over the porch. The ground floor is entirely occupied by an enclosed porch that spans the full facade and projects in front of the body: a solid painted skirt, a continuous band of glazing divided by slim white mullions with the entrance door just right of centre, a deep white head band, and a dark shallow roof slab whose fascia reads as the dark band under the second-floor windows. Five concrete steps with thin dark handrails climb to the door. On the left (west) flank a two-storey bay projects with two windows per floor; a brick chimney and a small dormer break the dark shingled roof, which has a ridge running front-to-back and gable ends at front and back. A large dark hedge hides the lower part of the porch, with trees behind and beside the house and a sidewalk and street in front.","parts":[{"name":"foundation","kind":"other","description":"concrete foundation band under the body"},{"name":"mainBlock","kind":"wall","description":"two-storey clapboard body"},{"name":"gableWall","kind":"wall","description":"triangular gable ends front and back"},{"name":"roofMain","kind":"roof","description":"dark front-gabled roof planes and ridge"},{"name":"sideWing","kind":"wall","description":"two-storey projecting bay on the west side"},{"name":"wingRoof","kind":"roof","description":"small roof over the side bay"},{"name":"chimney","kind":"stone","description":"brick chimney at the rear left"},{"name":"dormer","kind":"wall","description":"small dormer on the west roof slope"},{"name":"porch","kind":"wall","description":"enclosed porch skirt and head band"},{"name":"porchGlass","kind":"glass","description":"porch window sashes front and sides"},{"name":"porchFrame","kind":"frame","description":"porch mullions and door posts"},{"name":"porchRoof","kind":"roof","description":"porch roof slab and dark fascia"},{"name":"frontDoor","kind":"glass","description":"glazed front door in the porch"},{"name":"upperGlass","kind":"glass","description":"second-floor and gable windows on the front"},{"name":"sideGlass","kind":"glass","description":"side, bay and dormer windows"},{"name":"steps","kind":"stone","description":"concrete front steps"},{"name":"railing","kind":"metal","description":"thin handrails beside the steps"},{"name":"hedge","kind":"vegetation","description":"dark hedge across the front of the porch"},{"name":"trees","kind":"vegetation","description":"yard and street trees"},{"name":"pavement","kind":"pavement","description":"sidewalk and front path"},{"name":"road","kind":"road","description":"street in front of the house"}],"code":"const WHITE = '#e9e7e0';
  const ROOF = '#3b3b3d';
  const GLASS = '#28323a';
  const BRICK = '#8d7461';
  const CONC = '#b7b5ad';
  const GREEN = '#2e4a28';
  const PAVE = '#a8a39a';
  const ROADC = '#5a5a5d';
  const METAL = '#3a3a3c';

  const foundation = api.part('foundation', 'other', 'concrete foundation band');
  const mainBlock = api.part('mainBlock', 'wall', 'two storey clapboard body');
  const gableWall = api.part('gableWall', 'wall', 'triangular gable ends');
  const roofMain = api.part('roofMain', 'roof', 'front gabled roof');
  const sideWing = api.part('sideWing', 'wall', 'two storey side bay');
  const wingRoof = api.part('wingRoof', 'roof', 'side bay roof');
  const chimney = api.part('chimney', 'stone', 'brick chimney');
  const dormer = api.part('dormer', 'wall', 'roof dormer');
  const porch = api.part('porch', 'wall', 'enclosed porch');
  const porchGlass = api.part('porchGlass', 'glass', 'porch windows');
  const porchFrame = api.part('porchFrame', 'frame', 'porch mullions');
  const porchRoof = api.part('porchRoof', 'roof', 'porch roof slab');
  const frontDoor = api.part('frontDoor', 'glass', 'glazed front door');
  const upperGlass = api.part('upperGlass', 'glass', 'front upper windows');
  const sideGlass = api.part('sideGlass', 'glass', 'side and dormer windows');
  const steps = api.part('steps', 'stone', 'front steps');
  const railing = api.part('railing', 'metal', 'handrails');
  const hedge = api.part('hedge', 'vegetation', 'front hedge');
  const trees = api.part('trees', 'vegetation', 'yard trees');
  const pavement = api.part('pavement', 'pavement', 'sidewalk and path');
  const road = api.part('road', 'road', 'street');

  // ---- main body ----
  foundation.box(8.7, 0.55, 9.3, 0, 0, -0.8, 'other', CONC);
  mainBlock.box(8.4, 6.0, 9.0, 0, 0.55, -0.8, 'wall', WHITE);

  // ---- gable prism (front and rear gable walls) ----
  const gs = new THREE.Shape();
  gs.moveTo(-4.2, 0);
  gs.lineTo(4.2, 0);
  gs.lineTo(0, 2.8);
  gs.closePath();
  const gGeo = new THREE.ExtrudeGeometry(gs, { depth: 9.0, bevelEnabled: false });
  const gMesh = new THREE.Mesh(gGeo, api.material('wall', WHITE));
  gMesh.position.set(0, 6.55, -5.3);
  gableWall.add(gMesh);

  // ---- roof planes, ridge along z ----
  const ang = Math.atan2(2.8, 4.2);
  const slope = Math.sqrt(4.2 * 4.2 + 2.8 * 2.8) + 0.3;
  const rg = new THREE.BoxGeometry(slope, 0.16, 9.9);
  const rm = api.material('roof', ROOF);
  for (const s of [1, -1]) {
    const m = new THREE.Mesh(rg, rm);
    m.position.set(s * 2.1, 7.95, -0.8);
    m.rotation.z = -s * ang;
    roofMain.add(m);
  }
  roofMain.box(0.3, 0.18, 9.9, 0, 9.3, -0.8, 'roof', ROOF);

  // ---- west side bay ----
  sideWing.box(1.3, 5.45, 4.6, -4.75, 0.55, -0.7, 'wall', WHITE);
  wingRoof.box(1.7, 0.16, 5.0, -4.75, 5.98, -0.7, 'roof', ROOF);

  // ---- chimney and dormer ----
  chimney.box(0.72, 3.2, 0.72, -3.1, 6.8, -4.0, 'stone', BRICK);
  dormer.box(1.3, 1.2, 1.6, -2.95, 7.0, 1.0, 'wall', WHITE);
  dormer.box(1.6, 0.14, 1.9, -2.95, 8.2, 1.0, 'roof', ROOF);

  // ---- enclosed porch ----
  porch.box(8.4, 0.85, 2.5, 0, 0, 4.85, 'wall', WHITE);        // skirt
  porch.box(8.7, 0.80, 2.7, 0, 2.76, 4.95, 'wall', WHITE);      // head band

  const mull = 0.10;
  function frontRun(x0, x1, n) {
    const w = (x1 - x0 - (n - 1) * mull) / n;
    for (let i = 0; i < n; i++) {
      const cx = x0 + i * (w + mull) + w / 2;
      porchGlass.box(w, 1.9, 0.1, cx, 0.9, 6.16, 'glass', GLASS);
    }
    for (let i = 0; i <= n; i++) {
      let cx;
      if (i === 0) cx = x0 - mull / 2;
      else if (i === n) cx = x1 + mull / 2;
      else cx = x0 + i * (w + mull) - mull / 2;
      porchFrame.box(mull, 2.0, 0.16, cx, 0.86, 6.16, 'frame', WHITE);
    }
  }
  frontRun(-4.2, 0.72, 4);
  frontRun(1.78, 4.2, 2);

  porchGlass.box(0.1, 1.9, 1.4, 4.25, 0.9, 4.85, 'glass', GLASS);
  porchGlass.box(0.1, 1.9, 1.4, -4.25, 0.9, 4.85, 'glass', GLASS);

  frontDoor.box(0.96, 1.9, 0.1, 1.25, 0.85, 6.16, 'glass', GLASS);

  porchRoof.box(8.9, 0.22, 2.9, 0, 3.56, 4.95, 'roof', ROOF);

  // ---- front windows, second floor and gable ----
  upperGlass.box(1.15, 1.7, 0.12, -1.75, 4.0, 3.78, 'glass', GLASS);
  upperGlass.box(1.15, 1.7, 0.12, 1.75, 4.0, 3.78, 'glass', GLASS);
  upperGlass.box(0.85, 0.8, 0.12, -0.58, 7.3, 3.78, 'glass', GLASS);
  upperGlass.box(0.85, 0.8, 0.12, 0.58, 7.3, 3.78, 'glass', GLASS);

  // ---- side windows ----
  sideGlass.box(0.12, 1.7, 1.1, 4.28, 1.35, -3.0, 'glass', GLASS);
  sideGlass.box(0.12, 1.7, 1.1, 4.28, 1.35, -0.4, 'glass', GLASS);
  sideGlass.box(0.12, 1.6, 1.1, 4.28, 4.1, -3.0, 'glass', GLASS);
  sideGlass.box(0.12, 1.6, 1.1, 4.28, 4.1, -0.4, 'glass', GLASS);

  sideGlass.box(0.12, 1.7, 1.1, -5.46, 1.3, -1.95, 'glass', GLASS);
  sideGlass.box(0.12, 1.7, 1.1, -5.46, 1.3, 0.55, 'glass', GLASS);
  sideGlass.box(0.12, 1.6, 1.1, -5.46, 4.0, -1.95, 'glass', GLASS);
  sideGlass.box(0.12, 1.6, 1.1, -5.46, 4.0, 0.55, 'glass', GLASS);

  sideGlass.box(0.12, 0.7, 0.8, -3.66, 7.3, 1.0, 'glass', GLASS);

  // ---- front steps ----
  for (let i = 0; i < 5; i++) {
    const h = 0.17 * (i + 1);
    const d = 0.28 * (i + 1);
    steps.box(1.6, h, d, 1.25, 0, 6.0 + d / 2, 'stone', CONC);
  }

  const railGeo = new THREE.BoxGeometry(0.06, 0.06, 1.7);
  const railMat = api.material('metal', METAL);
  for (const rx of [0.5, 2.0]) {
    const m = new THREE.Mesh(railGeo, railMat);
    m.position.set(rx, 1.275, 6.7);
    m.rotation.x = Math.atan2(0.85, 1.4);
    railing.add(m);
  }

  // ---- planting ----
  hedge.box(4.6, 1.15, 1.1, -1.9, 0, 6.95, 'vegetation', GREEN);
  hedge.box(1.4, 0.9, 1.0, 3.2, 0, 6.85, 'vegetation', GREEN);

  function tree(x, z, h, r) {
    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.26, h, 8), api.material('vegetation', '#4a3b2c'));
    t.position.set(x, h / 2, z);
    trees.add(t);
    const f = new THREE.Mesh(new THREE.SphereGeometry(r, 12, 10), api.material('vegetation', GREEN));
    f.position.set(x, h + r * 0.5, z);
    trees.add(f);
  }
  tree(-9, -5, 5.0, 3.0);
  tree(9, -7, 5.0, 3.0);
  tree(-8, 5, 4.0, 2.4);

  // ---- ground: sidewalk, path, street ----
  pavement.box(20, 0.15, 2.6, 0, 0, 10.2, 'pavement', PAVE);
  pavement.box(1.6, 0.14, 1.5, 1.25, 0, 8.15, 'pavement', PAVE);
  road.box(26, 0.2, 6.5, 0, 0, 14.8, 'road', ROADC);","views":[{"photo":1,"x":0,"y":1.7,"z":15.5,"targetX":0,"targetY":5,"targetZ":4},{"photo":2,"x":4.5,"y":1.7,"z":14,"targetX":0,"targetY":5,"targetZ":3},{"photo":3,"x":-11,"y":3.5,"z":12.5,"targetX":-1,"targetY":4.5,"targetZ":0}]}
